  "tu.doPass": "Press Pass",
  "tu.wrongCards": "Select only the glowing cards",
  "tu.ngPass": "Press Pass here",
  "tu.ngNext": "Read the box and press Next",
  "tu.weak": "weak",
  "tu.strong": "strong",
  "tu.lvCard": "level card (7 this hand)",
  "tu.sj": "small joker",
